#pragma once
static constexpr char vaultWebPage[]=R"VAULT(<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Game Vault</title><style>
:root{color-scheme:dark;font:16px system-ui;background:#16181b;color:#f4f0e8}body{max-width:1200px;margin:40px auto;padding:0 24px}h1{margin-bottom:4px}p,small{color:#adb0b6}nav{display:flex;gap:10px;margin:30px 0;flex-wrap:wrap}button,a.action{background:#2f3237;border:1px solid #41454c;color:inherit;padding:12px 18px;border-radius:10px;cursor:pointer;text-decoration:none;display:inline-block}button.active,.primary{background:#f1bb68!important;color:#16181b!important}#games{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:18px}.card{background:#202327;padding:20px;border-radius:16px}.card img{width:76px;height:76px;object-fit:cover;border-radius:12px}.card h3{min-height:48px}.card button,.card a{margin:5px 4px 0 0}#status{white-space:pre-wrap;padding:18px;background:#202327;border-radius:12px;min-height:24px}button:disabled{opacity:.4;cursor:wait}input{background:#202327;color:inherit;border:1px solid #41454c;padding:12px;border-radius:8px;width:min(420px,90%)}footer{margin-top:30px;color:#adb0b6}select{padding:10px;background:#202327;color:inherit}#download{margin:15px 0}</style>
<h1>Game Vault</h1><p>Your console. Your library.</p><nav id="tabs"></nav><h2 id="heading"></h2><p id="hint"></p><input id="search" placeholder="Search games"><button id="refresh">Refresh</button><p id="status">Loading library…</p><div id="download"></div><div id="games"></div><footer>Keep Game Vault open. FTP remains available while browsing; active operations reserve storage. No access code required.</footer><script>
let library=[],tab='Library',busy=false;const $=id=>document.getElementById(id),tabs=['Backup','Restore','Library','Decrypted Backup'];
function el(tag,text){let n=document.createElement(tag);n.textContent=text;return n}function status(s){$('status').textContent=s}
async function api(path,post=false){let r=await fetch(path,{method:post?'POST':'GET',headers:post?{'X-Game-Vault':'1'}:{}});let data=await r.json();if(!r.ok)throw Error(data.error||r.status);return data}
async function task(fn){if(busy)return;busy=true;render();try{await fn()}catch(e){status(e.message)}finally{busy=false;render()}}
async function load(){status('Reading installed games and SD backups…');library=(await api('/api/library')).games;status('Library ready.');render()}
function button(node,title,fn){let b=el('button',title);b.disabled=busy;b.onclick=()=>task(fn);node.append(b)}
function render(){ $('tabs').replaceChildren();for(let name of tabs){let b=el('button',name);b.className=tab===name?'active':'';b.onclick=()=>{tab=name;render()};$('tabs').append(b)}$('heading').textContent=tab;$('hint').textContent=tab==='Decrypted Backup'?'Matched base ExeFS + RomFS, including executable files. Save a verified folder to SD or download a TAR to your PC. Installed updates are excluded.':tab==='Restore'?'Restore existing verified SD backups. Confirm each restore on the console.':tab==='Backup'?'Original installed archives: choose base or update separately. Backups are saved to /gamevault/backups.':'Installed games and available SD backups.';
 $('games').replaceChildren();for(let g of library.filter(g=>(tab==='Restore'?g.snapshots.length:tab==='Backup'||tab==='Decrypted Backup'?g.installed:true)&&g.name.toLowerCase().includes($('search').value.toLowerCase()))){let c=el('article','');c.className='card';if(g.icon){let i=new Image();let raw=g.icon.match(/../g);i.src='data:image/jpeg;base64,'+btoa(raw.map(v=>String.fromCharCode(parseInt(v,16))).join(''));c.append(i)}c.append(el('h3',g.name),el('small',g.id));
 if(tab==='Decrypted Backup'){button(c,'Dump to SD',async()=>{status('Preparing and copying matched files. Progress is shown on the console.');let r=await api('/api/dump-sd?title='+g.id,true);status('Verified SD dump: '+r.path)});button(c,'Prepare PC download',async()=>{status('Preparing matched ExeFS and RomFS…');let r=await api('/api/prepare?title='+g.id,true);$('download').replaceChildren();let a=el('a','Download '+g.name+' — matched base');a.className='action primary';a.href='/download/emulator?title='+g.id;$('download').append(a);status(r.files+' files ready. TAR includes export metadata and SHA256SUMS.txt. Extract it on your PC before packaging.');});}
 else if(tab==='Backup'){for(let [bit,name]of [[1,'Base game'],[2,'Update']])if(g.installed&bit)button(c,'Back up '+name,async()=>{status('Backing up and verifying '+name+'…');let r=await api('/api/backup?title='+g.id+'&mask='+bit,true);status('Verified: '+r.path)});for(let s of g.saves)button(c,'Save: '+s.name,async()=>{status('Backing up save…');let r=await api('/api/backup?title='+g.id+'&mask=4&save='+s.id,true);status('Verified: '+r.path)});}
 else if(tab==='Restore'){for(let s of g.snapshots){let row=el('div',s.label);for(let[bit,name]of [[1,'Base'],[2,'Update']])if(s.components&bit)button(row,'Restore '+name,async()=>{status('Confirm restore on the console.');await api('/api/restore?snapshot='+encodeURIComponent(s.id)+'&mask='+bit,true);status('Restore verified.');});c.append(row)}}else c.append(el('p',(g.installed?'Installed · ':'')+g.snapshots.length+' SD backups'));$('games').append(c)} }
$('search').oninput=render;$('refresh').onclick=()=>task(load);task(load);
</script></html>)VAULT";
